"""Build traceable audit registers; never writes production paths."""
from pathlib import Path
import collections, hashlib, json, re, struct, zlib

ROOT = Path(__file__).resolve().parents[3]
OUT = Path(__file__).resolve().parent
def dump(name, data):
    (OUT/name).write_text(json.dumps(data, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
def lines(path, start, end=None):
    return '\n'.join((ROOT/path).read_text(encoding='utf-8').splitlines()[start-1:(end or start)])

def png_size(p):
    b=p.read_bytes();assert b[:8]==b'\x89PNG\r\n\x1a\n',str(p)
    pos=8;compressed=[];size=None
    while pos<len(b):
        n=struct.unpack('>I',b[pos:pos+4])[0];kind=b[pos+4:pos+8];data=b[pos+8:pos+8+n]
        assert zlib.crc32(kind+data)&0xffffffff==struct.unpack('>I',b[pos+8+n:pos+12+n])[0],str(p)
        if kind==b'IHDR':size=list(struct.unpack('>II',data[:8]))
        if kind==b'IDAT':compressed.append(data)
        pos+=n+12
    assert size and zlib.decompress(b''.join(compressed)),str(p)
    return size

