        row={'path':rel,'domain':d,'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest(),'historicalContentMatches':prior in [hashlib.sha256(x).hexdigest() for x in [b,lf,lf.replace(b'\n',b'\r\n')]],'status':'readable'}
