matrix=[]
for r in sections:
    d=r['domain'];review=reviews[d];rs=review.read_text(encoding='utf-8').splitlines()
    found=[(i,l) for i,l in enumerate(rs,1) if l.startswith('|') and r['anchor'] in l]
    if not found:
        needles={ 'topic-1-1-cia-triad':['D1-02 —'], 'topic-3-review-scenarios':['Review distinctions, R3:','Review traps, R3:','Keyword matrix, R3:','Review scenarios, R3:'], 'topic-4-review-scenarios':['Review distinctions, R4:','Review traps, R4:','Keyword matrix, R4:','Review scenarios, R4:'] }[r['anchor']]
        found=[(i,l) for i,l in enumerate(rs,1) if l.startswith('|') and any(n in l for n in needles)]
    assert found,r['anchor']
    evidence='\n'.join(l for _,l in found)
    actions=[]
    for term in re.findall('|'.join(re.escape(x) for x in allowed+list(normalize)),evidence):
        mapped=normalize.get(term,term)
        if mapped not in actions:actions.append(mapped)
    assert actions,r['anchor']
    matrix.append({**r,'readingPath':f'content/isc2-cc-2026/reading/domain-{d}.md','primaryClassification':actions[0],'secondaryRecommendations':actions[1:],'reviewFile':review.name,'reviewLines':[i for i,_ in found],'assessment':evidence,'coverageBasis':'Prior subsection review retained after current content reconciliation; current anchor/line checks'})
